proposal.patched_block:
resource "aws_iam_policy" "wildcard_admin" {
  name        = "Company-Wildcard-Policy"
  description = "Intentionally excessive permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "arn:aws:s3:::company-internal-data/*"
      }
    ]
  })
}
